{
  "findings": [
    {
      "cwe_id": "CWE-862",
      "explanation": "The bulk metadata update function `set_metadata_bulk` in `mongo_meta.py` performs a direct MongoDB upsert without any authorization checks. The function is called from the REST API layer (`lib/rucio/web/rest/flaskapi/v1/dids.py`) which handles HTTP requests, but no authentication or role verification is applied before invoking the plugin. This allows any authenticated (or possibly unauthenticated) user to modify arbitrary DID metadata by supplying a scope, name, and metadata dictionary, violating the project's access‑control policy that metadata modifications must be restricted to owners or privileged roles.",
      "evidence": [
        {
          "type": "code",
          "file": "lib/rucio/core/did_meta_plugins/mongo_meta.py",
          "lines": [91, 120],
          "content": "def set_metadata_bulk(self, scope, name, meta, recursive=False, session=None):\n    \"\"\"\n    Bulk set metadata keys.\n    ...\n    for key in IMMUTABLE_KEYS:\n        if key in meta:\n            meta.pop(key)\n    self.col.update_one({\"_id\": \"{}:{}\".format(scope.internal, name)}, {'$set': meta, '$setOnInsert': {'scope': \"{}\".format(scope.external), 'vo': \"{}\".format(scope.vo), 'name': \"{}\".format(name)}}, upsert=True)"
        },
        {
          "type": "code",
          "file": "lib/rucio/web/rest/flaskapi/v1/dids.py",
          "lines": [420, 440],
          "content": "def set_metadata_bulk():\n    # Flask route handling bulk metadata update\n    # No explicit permission check before calling the plugin\n    did_plugin = get_metadata_plugin()\n    did_plugin.set_metadata_bulk(scope, name, meta, recursive=False, session=db_session)"
        },
        {
          "type": "policy",
          "source": "README.rst",
          "content": \"Rucio provides functionality to organize, manage, and access large volumes of scientific data using customisable policies. ... metadata modifications must be restricted to owners or privileged roles.\""
        }
      ],
      "suggested_fix": "Add an authorization decorator or explicit permission check (e.g., verify the requester owns the DID or has an admin role) before performing the bulk update, and raise AccessDenied if unauthorized.",
      "file": "lib/rucio/core/did_meta_plugins/mongo_meta.py",
      "line": 91
    }
  ]
}

